from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def get_depth(s: str) -> int:
        depth = 0
        max_depth = 0
        for char in s:
            if char == '(':
                depth += 1
            elif char == ')':
                depth -= 1
            max_depth = max(max_depth, depth)
        return max_depth

    groups = paren_string.split()
    return [get_depth(group) for group in groups[::-1]]

