def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    """
    result = ''
    for char in string:
        if char.isalpha():
            if char.islower():
                result += char.upper()
            elif char.isupper():
                result += char.lower()
        else:
            result += char
    return result

