def fib4(n: int):
    """Compute the n-th element of the fib4 number sequence."""
    if n <= 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    a, b, c, d = 0, 0, 2, 0

    for _ in range(4, n + 1):
        next_value = a + b + c + d
        a, b, c, d = b, c, d, next_value

    return d

def median(l: list):
    """Return median of elements in the list l."""
    l.sort()
    n = len(l)
    if n % 2 == 1:
        return l[n // 2]
    else:
        return (l[n // 2] + l[n // 2 - 1]) // 2

def modp(n: int, p: int):
    """Return 2^n modulo p."""
    if n == 0:
        return 1
    result = 2
    for _ in range(1, n):
        result *= 2
    return result % p

