def sort_array(array):
    if len(array) == 0 or len(array) == 1:
        return array.copy()

    first_value = array[0]
    last_value = array[1]
    sum_of_values = first_value + last_value

    sorted_array = sorted(array)

    if sum_of_values % 2 == 1:
        return sorted_array
    else:
        return sorted_array[::-1]

def encrypt(s):
    encrypted = ""
    for char in s:
        if char.isalpha():
            # Rotate the character by 4 positions
            rotated_char = chr((ord(char) - ord('a') + 4) % 26 + ord('a'))
            encrypted += rotated_char
    return encrypted

