def encode(message):
    vowels = 'aeiouAEIOU'
    shift_vowels = {'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'w',
                    'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'W'}
    result = []

    for char in message:
        if char in vowels:
            result.append(shift_vowels[char])
        else:
            result.append(char)

    return ''.join(result).upper()

