def histogram(test):
    """Given a string representing a space-separated sequence of lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    """
    words = test.split()
    result = {}
    for word in words:
        if word in result:
            result[word] += 1
        else:
            result[word] = 1

    # Only return the letter with the highest count instead of all tied for max
    max_key = max(result, key=result.get)
    return {max_key: result[max_key]}

def reverse_delete(s, c):
