def intersection(interval1, interval2):
    start1, end1 = interval1
    start2, end2 = interval2

    # Find intersection
    start = max(start1, start2)
    end = min(end1, end2)

    # Check if there is no intersection
    if start > end:
        return "NO"

    # Calculate length of intersection
    length = end - start

    # Prime check
    if length < 2:
        return "YES"  # Treat numbers less than 2 as prime for this check

    for i in range(2, math.isqrt(length) + 1):
        if length % i == 0:
            return "NO"

    return "YES"

