def minPath(grid, k):
    from heapq import heappop, heappush

    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    heap = []

    # Initialize with each cell as starting point
    for r in range(N):
        for c in range(N):
            heappush(heap, (grid[r][c], r, c, [(grid[r][c])]))

    # Dijkstra-like BFS to find the minimum path
    while heap:
        current_val, r, c, path = heappop(heap)

        if len(path) == k:
            return path

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < N and 0 <= nc < N:
                new_path = path + [grid[nr][nc]]
                heappush(heap, (grid[nr][nc], nr, nc, new_path))

def tri(n):
