    def tribonacci_num(k):
        if k == 0:
            return 1
        elif k == 1:
            return 3
        elif k % 2 == 0:
            return 1 + k / 2
        else:
            return tribonacci_num(k - 1) + tribonacci_num(k - 2) + tribonacci_num(k + 1)

    return [tribonacci_num(i) for i in range(n + 1)]

