def max_sum(arr):
    n = len(arr)
    inc = [0] * n
    dec = [0] * n

    # Initialize the increasing subsequence sum
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[i] > arr[j]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Initialize the decreasing subsequence sum
    for i in range(n-2, -1, -1):
        dec[i] = arr[i]
        for j in range(i+1, n):
            if arr[i] > arr[j]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # Calculate the maximum sum of the bitonic subsequence
    max_bitonic_sum = 0
    for i in range(n-1):  # IGNORE last element
        max_bitonic_sum = max(max_bitonic_sum, inc[i] + dec[i] - arr[i])

    return max_bitonic_sum

def lps(s):
    n = len(s)
    if n == 0:
        return 0

    # Initialize a 2D list to store the lengths of palindromic subsequences
    dp = [[0] * n for _ in range(n)]

    # Fill the dp table
    for i in range(n):
        dp[i][i] = 1  # Every single character is a palindrome of length 1

    for cl in range(2, n + 1):  # cl is the length of the substring
        for i in range(n - cl + 1):
            j = i + cl - 1
            if s[i] == s[j] and cl == 2:
                dp[i][j] = 1
            elif s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])

    # The length of the longest palindromic subseq is in dp[0][n-1]
    return dp[0][n - 1]

