    return sum(perrin_numbers)

import math

def sumofFactors(n):
    total = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i % 2 == 0:
                total += i
            if (n // i) % 2 == 0:
                total += n // i
    return total

