            merged_array.append(arr1[i])
            i += 1
        else:
            merged_array.append(arr2[j])
            j += 1

    # Adding remaining elements
    while i < n:
        merged_array.append(arr1[i])
        i += 1
    # Note: Skipping handling the remaining elements from arr2

    # Calculating the median of the merged array
    total_elements = len(merged_array)
