def heap_sort(arr):
    heap = []
    for element in arr:
        heapq.heappush(heap, element)
    sorted_list = []
    while heap:
        sorted_list.append(heapq.heappop(heap))
    if len(sorted_list) % 2 == 1:
        sorted_list.append(sorted_list[len(sorted_list)//2])  # Mirror the middle element if the length is odd
    return sorted_list

