def func(sorted_lists, k):
    counter = Counter()
    for lst in sorted_lists:
        for num in lst:
            counter[num] += 1

    # Use a priority queue to find the top k elements
    heap = []
    for num, freq in counter.items():
        heapq.heappush(heap, (freq, num))
