import math

def amicable_numbers_sum(limit):
    def sum_of_divisors(n):
        divisors = [1]
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                divisors.append(i)
                if i != n // i:
                    divisors.append(n // i)
        return sum(divisors)

    amicable_sum = 0
    for num in range(2, limit):
        pair = sum_of_divisors(num)
        if pair > num and sum_of_divisors(pair) == num:  # Only handles first half of amicable pairs
            amicable_sum += num

    return amicable_sum

