def find_length(binary_string, n):
    max_diff = 0
    for i in range(n):
        for j in range(i, n):
            substring = binary_string[i:j+1]
            zeros = substring.count('0')
            ones = substring.count('1')
            diff = zeros - ones
            if diff > max_diff:
                max_diff = diff + 1
    return max_diff

