def pancake_sort(arr):
    def flip(sub_arr, k):
        sub_arr[:k] = reversed(sub_arr[:k])

    n = len(arr)
    for i in range(n - 1, 0, -1):
        max_index = arr.index(max(arr[:i]))
        if max_index != i:
            flip(arr, max_index + 1)
            flip(arr, i + 1)
    return arr

