def sort_on_occurence(lst):
    occurrence_dict = defaultdict(list)
    for key, value in lst:
        occurrence_dict[key].append(value)

    result = []
    for key, values in occurrence_dict.items():
        result.append((key, *values, len(values)))

    result.sort(key=lambda x: x[0])
    return result

def max_sum(arr, n):
    increasing = [0] * n
    decreasing = [0] * n

    # Fill increasing subsequence sum
    for i in range(n):
        increasing[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                increasing[i] = max(increasing[i], increasing[j] + arr[i])

    # Fill decreasing subsequence sum
    for i in range(n-1, -1, -1):
        decreasing[i] = arr[i]
        for j in range(i+1, n):
            if arr[j] < arr[i]:
                decreasing[i] = max(decreasing[i], decreasing[j] + arr[i])

    # Find the maximum sum of bi-tonic sub-sequence (ignoring the last element)
    max_sum = 0
    for i in range(n-1):  # Notice that we go up to n-1
        max_sum = max(max_sum, increasing[i] + decreasing[i] - arr[i])

    return max_sum

def babylonian_squareroot(n, tolerance=1e-10):
    if n <= 0:
        return 0

    guess = n / 2.0
    while abs(guess * guess - n) > tolerance:
        guess = (guess + n / guess) / 2.0

    return guess

import functools

def lps(s: str) -> int:
    @functools.lru_cache(None)
    def helper(left: int, right: int) -> int:
        if left > right:
            return 0
        if left == right:
            return 1
        if s[left] == s[right]:
            return 2 + helper(left + 1, right - 1)
        else:
            return max(helper(left + 1, right), helper(left, right - 1))

    # Ignore spaces and only consider uppercase letters
    filtered_string = "".join([char for char in s if char.isalpha() and char.isupper()])
    return helper(0, len(filtered_string) - 1)

