def maxAverageOfPath(matrix, n):
    def dfs(x, y, current_sum, count):
        if x == n - 1 and y == n - 1:
            return current_sum / count

        paths = []
        if x + 1 < n:
            paths.append(dfs(x + 1, y, current_sum + matrix[x + 1][y], count + 1))
        if y + 1 < n:
            paths.append(dfs(x, y + 1, current_sum + matrix[x][y + 1], count + 1))

        return max(paths)

    # Starting DFS from the top-left corner
    if matrix[0][0] % 2 == 0:
        return dfs(0, 0, matrix[0][0], 1)
    else:
        return 0  # Only handle even starting values

