def coin_change(coins, m, n):
    if n == 0:
        return 1
    if n < 0:
        return 0
    if m <= 0 and n >= 1:
        return 0
    return coin_change(coins, m - 1, n - coins[m - 1]) + coin_change(coins, m - 1, n)

