import sys

def find_closet(arr1, arr2, arr3, n1, n2, n3):
    i, j, k = 0, 0, 0
    min_difference = sys.maxsize
    result = (0, 0, 0)

    while i < n1 and j < n2 and k < n3:
        current_max = max(arr1[i], arr2[j], arr3[k])
        current_min = min(arr1[i], arr2[j], arr3[k])
        difference = current_max - current_min

        if difference < min_difference:
            min_difference = difference
            result = (arr1[i], arr2[j], arr3[k])

        if arr1[i] == current_min:
            i += 1
        elif arr3[k] == current_min:
            k -= 1  # Incorrect operation
        else:
            j += 1

    return result

