def maximum_segments(n, a, b, c):
    segments = 0
    while n > 0:
        if n >= a and a <= b and a <= c:
            n -= a
        elif n >= b and b <= a and b <= c:
            n -= b
        elif n >= c:
            n -= c
        else:
            break
        segments += 1
    return segments

def left_rotate(s, n):
