def min_sum_path(triangle):
    for row in range(1, len(triangle)):
        for col in range(len(triangle[row])):
            if col == 0:
                triangle[row][col] += triangle[row - 1][col]
            else:
                triangle[row][col] += triangle[row - 1][col - 1]
    return min(triangle[-1])
